import {renderLayout,selectLayoutObject} from './layout-console.mjs';
import {renderWorkerSupport} from './worker-support.mjs';
import {governmentPanel,roadMap,roadCaption} from './government-data.mjs';
import {renderWearable,renderObservation,renderLiveScene,renderLiveWatch,liveObjectTransform} from './on-site-display.mjs';
import {LIVE_SCENARIOS,responses,scenarioForCase,createDemo,syncDemo,hazardEvent,livePhase,holdAtDetection,workerDistance,RESPONSE_SECONDS} from './live-demo.mjs';
import {esc,num,card,kv,pill} from './visuals.mjs';
import {createSafety,selectedSite,activeEvents,coverage,validity,delivery,stamp,STAGES,CASES,safetyAction,safetyInput,tickSafety,safetyExport} from './safety-model.mjs';
export const workerSafety=createSafety();
const demo=createDemo();
const tabs=[['live','On-site protection','01'],['worker','Workers & support','02'],['layout','Site layout','03'],['supervisor','Multi-site supervision','04']];
const B=(label,action,value='',cls='',disabled=false)=>`<button class="btn ${cls}" data-ws="${action}" data-value="${esc(value)}" ${disabled?'disabled':''}>${label}</button>`;
const body=html=>`<div class="card-body">${html}</div>`;
const select=(label,key,value,options)=>`<label class="ws-field">${label}<select data-ws-input="${key}" aria-label="${label}">${options.map(([v,t])=>`<option value="${v}" ${String(value)===String(v)?'selected':''}>${t}</option>`).join('')}</select></label>`;
const input=(label,key,value,min,max,step=1)=>`<label class="ws-field">${label}<input type="number" data-ws-input="${key}" aria-label="${label}" value="${value}" min="${min}" max="${max}" step="${step}"></label>`;
const check=(label,key,value)=>`<label class="ws-check"><input type="checkbox" data-ws-input="${key}" ${value?'checked':''}>${label}</label>`;
const badge=(text,kind='')=>`<span class="ws-badge ${kind}">${esc(text)}</span>`;
const dateLabel=value=>new Intl.DateTimeFormat('en-AU',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(value));
const active=site=>activeEvents(site).filter(e=>e.condition);
let localVideo=null;
let safetyExtension=()=>'';
export function setSafetyExtension(renderer){safetyExtension=renderer;}
export function publicNoticePage(){return `<div class="ws" lang="en-AU">${workerSafety.message?`<div class="ws-feedback" role="status">${esc(workerSafety.message)}</div>`:''}${publicView(selectedSite(workerSafety))}</div>`;}
export function safetyPage(){const local=selectedSite(workerSafety),site=workerSafety.tab==='supervisor'&&!local.online?{...local,events:local.cloud,edge:local.cloudHealth!=='degraded',worker:{...local.worker,duty:local.cloudDuty??local.worker.duty}}:local,events=active(site),hazards=events.filter(e=>e.type==='hazard'),support=events.filter(e=>e.type==='support');return `<div class="ws" lang="en-AU"><div class="ws-intro"><span class="ws-eyebrow">WORKER SAFETY / MELBOURNE, VIC</span><span>${badge('Real road context + simulated safety','demo')} ${badge('Workflow prototype')}</span></div>${workerSafety.tab==='supervisor'?`<div class="ws-toolbar"><label class="ws-site-label">Selected site<select data-ws-input="site" aria-label="Selected site">${workerSafety.sites.map(s=>`<option value="${s.id}" ${s.id===site.id?'selected':''}>${s.name} · ${s.road}</option>`).join('')}</select></label><div class="ws-link-status"><i class="dot" style="background:${site.online?'var(--green)':'var(--orange)'}"></i>${site.online?'Cloud sync active':`Internet offline · ${site.pending.length} awaiting sync`}</div>${B(site.online?'Simulate internet outage':'Restore internet','online','','small')}</div>`:''}${workerSafety.tab==='live'?liveStatus(site):''}${['public','supervisor','live','worker','layout'].includes(workerSafety.tab)?'':`<div class="ws-metrics"><div><span>External hazards</span><strong class="${hazards.length?'red':''}">${hazards.length?`${hazards.length} active`:!site.edge||!site.layout.power||site.occluded?'Status unknown':'No trigger'}</strong><small>${!site.edge||!site.layout.power||site.occluded?'Last known events retained':'Synthetic vehicle / pedestrian observations'}</small></div><div><span>Worker support</span><strong class="${support.length?'orange':''}">${support.length?`${support.length} to follow up`:'No requests'}</strong><small>Continuous duty ${Math.floor(site.worker.duty)} min</small></div><div><span>Data & protection</span><strong class="${validity(site)==='degraded'?'orange':''}">${validity(site)==='degraded'?'Degraded':'Demo feed available'}</strong><small>Heart rate: ${site.worker.heart==='missing'?'Missing':'Demo input'} · Not a health diagnosis</small></div><div><span>Site configuration</span><strong>v${site.layout.revision} <small>${site.layout.confirmed===site.layout.revision?'Demo confirmed':'Unconfirmed'}</small></strong><small>Checks pending: ${coverage(site.layout).gaps.length} · ${site.layout.template==='corner'?'Corner':'Straight'} road</small></div></div>`}<nav class="ws-tabs" aria-label="Worker safety functions">${tabs.map(([id,label,n])=>`<button data-ws="tab" data-value="${id}" class="${workerSafety.tab===id?'active':''}" ${workerSafety.tab===id?'aria-current="page"':''}><small>${n}</small>${label}</button>`).join('')}</nav>${workerSafety.message?`<div class="ws-feedback" role="status">${esc(workerSafety.message)}</div>`:''}${!site.online?`<div class="alert-banner">Internet disconnected. Local alerts continue in the simulation. Supervisor data is from ${stamp(site.lastSync)} and is stale; ${site.pending.length} events await sync.</div>`:''}${({live,worker,layout,supervisor,public:publicView}[workerSafety.tab])(site)}${workerSafety.tab==='live'?'':safetyExtension(workerSafety.tab,local)}</div>`;}

function eventCard(event,site,cloud=false,receiptControl=true){const d={delivered:'Delivered (simulated)',failed:'Delivery failed',unknown:'Delivery unknown'};return `<article class="ws-event ${event.severity}"><div class="ws-event-head">${badge(event.severity==='high'?'Immediate action':event.type==='data'?'Data / protection':'Advisory',event.severity)}<span>${esc(event.id)} · ${stamp(event.created)}</span>${badge(STAGES[event.stage])}</div><h3>${esc(event.title)}</h3><p>${esc(event.basis)}</p><div class="ws-event-meta"><span>Notification: ${d[event.delivery]}</span><span>Worker: ${event.acknowledged?'Acknowledged':'Not acknowledged'}</span><span>Owner: ${event.owner||'Unassigned'}</span><span>Trigger configuration v${event.configVersion} · ${event.configConfirmed?'Demo confirmed':'Unconfirmed'}</span></div><div class="ws-event-condition">${event.stage===3?esc(event.result):event.condition?'● Condition active or unconfirmed. Acknowledgement does not clear the hazard.':'○ Trigger cleared. Awaiting owner review and closure.'}</div>${cloud?'':`<div class="actions">${event.stage===3?'':`${(receiptControl||!event.condition)?B(event.acknowledged?'Worker acknowledged':'Acknowledge alert','ack',event.id,'small',event.acknowledged||event.delivery!=='delivered'||delivery(site)!=='delivered'):''}${event.delivery!=='delivered'?B('Retry notification','retry',event.id,'small'):''}${event.stage===0?B('Assign supervisor','take',event.id,'small primary'):''}${event.stage===1?B(event.type==='support'?'Arrange relief / support':'Start response','progress',event.id,'small primary'):''}${B('Review & close','close',event.id,'small',!event.owner||event.condition)}`}</div>`}</article>`;}
const LIVE_ICONS={car:'M5 17H3v-7l2-6h14l2 6v7h-2M5 17v3m14-3v3M3 10h18M7 14h1m8 0h1M5 17h14',bolt:'M13 2 4 14h7l-1 8 9-12h-7l1-8Z',sos:'M12 3 2 21h20L12 3Zm0 6v5m0 3v1',walk:'M12 5a2 2 0 1 0 0-.01M10 22l2-7 2 3v4M8 12l4-4 4 3m-4-3v7',sensor:'M10 12a2 2 0 1 0 4 0 2 2 0 1 0-4 0M16.2 7.8a6 6 0 0 1 0 8.4M7.8 16.2a6 6 0 0 1 0-8.4M19 5a10 10 0 0 1 0 14M5 19A10 10 0 0 1 5 5',platform:'M4 7h16v10H4zM8 12h.01M12 12h.01M7 17v3m10-3v3M9 4v3m6-3v3',sign:'M4 4h16v10H4zM12 14v7M8 21h8M8 8h8M8 11h5',alarm:'M6 8a6 6 0 0 1 12 0c0 7 3 9 3 9H3s3-2 3-9M10 21h4',supervisor:'M5 3h14v18H5zM11 18h2'};
const liveIcon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${LIVE_ICONS[name]}"/></svg>`;
function liveStatus(site){const up=site.edge&&site.layout.power&&!site.occluded,device=site.worker.connected;return `<div class="live-status" aria-label="System status"><span class="${up?'ok':'warn'}">${up?'Site connected':'Site equipment unavailable'}</span><span class="${device?'ok':'warn'}">${device?'Worker device connected':'Worker device disconnected'}</span><span class="sim">Simulation mode</span></div>`;}
function liveView(site){
 syncDemo(demo,site);
 const key=scenarioForCase(site.case),sc=LIVE_SCENARIOS[key],phase=livePhase(site,demo),event=hazardEvent(site),running=phase!=='idle';
 const response=responses(key).find(r=>r.id===demo.response);
 return {key,sc,phase,event,response,pedestrian:Boolean(sc.pedestrian),title:running?sc.title:'',speed:sc.speed,watch:sc.watch,distance:event?workerDistance(site):null,
  caption:phase==='idle'?`${site.name} · simulated scene`:phase==='moving'?`Sensor C1 tracking ${sc.pedestrian?'P-01':'V-01'}`:phase==='clear'?'No hazard · monitoring':phase==='resolved'?'Response complete':'Hazard in detection zone'};
}
function liveTimeline(site,v){
 const t=n=>stamp(n).slice(0,5),lines=[],e=v.event;
 if(e){lines.push([e.lastNotifiedAt,'Hazard detected','hot']);lines.push([e.lastNotifiedAt,e.delivery==='delivered'?'Worker alert sent automatically':'Worker alert not delivered','hot']);
  if(v.response)lines.push([demo.respondedAt,v.response.done,'act']);
  if(e.acknowledged)lines.push([demo.ackAt??e.updated,'Worker acknowledged','ok']);
  if(v.phase==='resolved'){const at=demo.respondedAt+RESPONSE_SECONDS;lines.push([at,v.response.id==='supervisor'?'Supervisor on the way':v.sc.outcome,'ok']);lines.push([at,'Risk reduced','ok']);}}
 else if(v.phase==='clear')lines.push([site.clock,'Vehicle passed · no hazard','ok']);
 lines.sort((a,b)=>a[0]-b[0]);
 return `<div class="live-timeline"><h3>This simulation</h3>${lines.length?`<ol>${lines.map(([at,text,kind],i)=>`<li class="${kind}" style="--i:${i}"><time>${t(at)}</time><span>${esc(text)}</span></li>`).join('')}</ol>`:'<p>Events appear here as the system responds.</p>'}</div>`;
}
function liveRisk(v){
 const names=['LOW','LOW','MEDIUM','HIGH'],from=Math.max(2,v.sc.risk||2);
 if(v.phase==='resolved')return `<div class="live-risk is-dropping from-${from}" aria-label="Risk level reduced to low"><div class="live-risk-head"><span>RISK LEVEL</span><span class="live-risk-names">${from===3?'<b class="n3">HIGH</b>':''}<b class="n2">MEDIUM</b><b class="n1">LOW</b></span></div><div class="live-risk-bars"><i></i><i></i><i></i></div></div>`;
 const level=v.phase==='detected'||v.phase==='responding'?from:1;
 return `<div class="live-risk level-${level}"><div class="live-risk-head"><span>RISK LEVEL</span><span>${names[level]}</span></div><div class="live-risk-bars">${[1,2,3].map(i=>`<i class="${i<=level?'on':''}"></i>`).join('')}</div></div>`;
}
function liveStage(site,v){
 const again=`<div class="live-again">${B('Reset simulation','demo-reset','','dark')}${B('Try another scenario','demo-reset','','')}</div>`;
 if(v.phase==='idle')return `<div class="live-stage-head"><h2>Choose a situation to simulate</h2><p>The simulation starts as soon as you choose.</p></div><div class="live-choices">${Object.entries(LIVE_SCENARIOS).map(([id,s])=>`<button class="live-choice ${id==='normal'?'calm':''}" data-ws="demo-start" data-value="${id}"><span class="live-choice-icon">${liveIcon(s.icon)}</span><strong>${esc(s.title)}</strong><span>${esc(s.line)}</span></button>`).join('')}</div>`;
 if(v.phase==='moving')return `<div class="live-stage-head"><h2><i class="live-pulse"></i>Simulating: ${esc(v.sc.title.toLowerCase())}</h2><p>Sensor C1 is tracking the ${v.pedestrian?'pedestrian':'vehicle'}. The platform checks every position against the detection zone.</p></div><div class="live-progress"><i></i></div>`;
 if(v.phase==='detected')return `<div class="live-detected"><div><h2 class="hot">Hazard detected</h2><dl class="live-facts"><div><dt>${v.pedestrian?'Object':'Vehicle speed'}</dt><dd>${v.pedestrian?'Pedestrian':`${v.speed}<small>simulated</small>`}</dd></div><div><dt>Worker distance</dt><dd>${v.distance} m</dd></div><div><dt>Risk level</dt><dd class="${v.sc.risk===3?'hot':'warn'}">${v.sc.risk===3?'HIGH':'MEDIUM'}</dd></div></dl><p>The worker’s watch was alerted automatically. Choose how the system should respond:</p></div><div class="live-actions">${responses(v.key).map((r,i)=>`<button class="live-action ${i===0?'primary':''}" data-ws="demo-respond" data-value="${r.id}">${liveIcon(r.id==='supervisor'?'supervisor':v.pedestrian?'alarm':'sign')}${esc(r.label)}</button>`).join('')}</div></div>`;
 if(v.phase==='responding'){const target=v.response.id==='supervisor'?'supervisor':v.pedestrian?'alarm':'sign';return `<div class="live-stage-head"><h2>Sending to ${esc(v.response.target.toLowerCase())}</h2></div><div class="live-chain" style="--d:${RESPONSE_SECONDS}s"><span class="live-chain-line"></span><span class="live-chain-dot"></span>${[['sensor','Sensor C1'],['platform','Safety platform'],[target,v.response.target]].map(([ico,label],i)=>`<div class="live-node n${i}"><span>${liveIcon(ico)}</span>${esc(label)}</div>`).join('')}</div>`;}
 if(v.phase==='resolved'){const items=['Worker alerted',v.response.id==='supervisor'?'Supervisor on the way':v.sc.outcome,'Risk reduced'];return `<div class="live-result"><div><h2 class="ok">Hazard handled</h2><ul class="live-outcomes">${items.map((t,i)=>`<li style="--i:${i}">${esc(t)}</li>`).join('')}</ul></div>${again}</div>`;}
 return `<div class="live-result"><div><h2 class="ok">Normal traffic · no action needed</h2><ul class="live-outcomes"><li style="--i:0">No hazard detected</li><li style="--i:1">System keeps monitoring</li></ul></div>${again}</div>`;
}
function live(site){
 const v=liveView(site),list=activeEvents(site);
 return `<div class="live" data-live-phase="${v.phase}"><div class="live-grid"><div class="live-main">${renderLiveScene(site,{...v,response:demo.response})}<section class="live-stage phase-${v.phase}" aria-live="polite">${liveStage(site,v)}</section></div><aside class="live-side">${renderLiveWatch(site,v)}${liveRisk(v)}${liveTimeline(site,v)}</aside></div><details class="ws-details live-details" data-connectivity><summary>View event details</summary><div class="live-details-body"><div class="ws-event-list">${list.length?list.slice(0,6).map(e=>eventCard(e,site,false,false)).join(''):'<div class="empty">No events yet.</div>'}</div><div class="actions">${B('Mark hazard condition cleared','clear','','small')}${B('Full event register','tab','supervisor','small')}</div>${card('Connectivity checks','An internet outage does not mean local equipment has failed',body(`<div class="ws-flow"><span class="${site.edge&&site.layout.power?'':'failed'}">Video / zone observations</span><b>→</b><span class="${site.edge&&site.layout.power?'':'failed'}">On-site processing</span><b>→</b><span class="${delivery(site)==='delivered'?'':'failed'}">Worker vibration / sound / visual alert</span></div><div class="actions section-gap">${B(site.edge?'Simulate device failure':'Restore site equipment','edge','','small')}${B(site.occluded?'Restore visibility':'Simulate obstruction','occlusion','','small')}${B(site.worker.connected?'Disconnect wearable':'Reconnect wearable','wearable','','small')}</div><p class="note">${validity(site)==='degraded'?'Protection degraded. Backup sound and light alerts activated (simulated); an on-site check is required.':'Local emergency alert path available (simulated).'} Wireless range, power and offline reliability require hardware testing.</p>`))}<details class="ws-details" data-local-video><summary>Load local video (replay only)</summary><p>Video plays locally in your browser and is not uploaded or analysed.</p><input type="file" accept="video/*" data-ws-file aria-label="Load local video">${localVideo?`<video controls src="${localVideo}" class="ws-video"></video>`:''}</details></div></details></div>`;
}
function worker(site){return renderWorkerSupport(site);}

function layout(site){return renderLayout(site);}

function supervisor(site){const all=workerSafety.sites.flatMap(s=>(s.online?s.events:s.cloud).map(e=>({...e,site:s}))).sort((a,b)=>(a.stage===3)-(b.stage===3)||(a.severity==='high'?-1:1)-(b.severity==='high'?-1:1)||b.created-a.created);return `<div class="ws-section-title"><div><h2>Multi-site supervisor dashboard</h2><p class="sub">Follow up by priority and owner / retain last known events offline</p></div>${B('Simulate requests at other sites','multi','','small')}</div><div class="ws-site-grid">${workerSafety.sites.map(s=>{const known=s.online?s.events:s.cloud,count=known.filter(e=>e.stage!==3).length;return `<article class="ws-site-card ${!s.online?'stale':''}"><div class="ws-event-head">${badge(s.id)}${badge(!s.online?'Stale data':validity(s)==='degraded'?'Protection degraded':count?'Action required':'Demo feed available',!s.online?'watch':'')}</div><h3>${s.name}</h3><p>${s.road}</p>${kv('Works hours','08:00–17:00')}${kv('Workers on site',`${s.online?s.workers:s.cloudWorkers??s.workers} workers`)}${kv('Events visible to supervisor',`${count} events`)}${kv('Device data',!s.online?'Last known: '+(s.cloudHealth==='degraded'?'Degraded':'Available (simulated)'):validity(s)==='degraded'?'Degraded':'Available (simulated)')}${kv('Last synced',stamp(s.lastSync))}${kv('Pending / synced updates',`${s.pending.length} / ${s.synced}`)}<div class="actions section-gap">${B(s.id===site.id?'Selected site':'Open site','site',s.id,'small',s.id===site.id)}</div></article>`;}).join('')}</div><div class="section-gap">${card('Event & response register','Stable event IDs, separate configuration versions / acknowledgement does not clear a hazard',body(`${all.length?all.map(e=>`<div class="ws-ledger-site">${badge(e.site.name)}${!e.site.online?badge('Last known / stale','watch'):''}${e.site.id!==site.id?B('Open response','site',e.site.id,'small'):''}</div>${eventCard(e,e.site,!e.site.online||e.site.id!==site.id)}`).join(''):'<div class="empty">No events yet. Choose an on-site scenario or simulate requests from other sites.</div>'}`))}</div>`;}
function publicMap(){const site=selectedSite(workerSafety);return roadMap(site.id,Boolean(site.notice.published))+roadCaption(site.id);}
function publicView(site){const n=site.notice;return `<div class="ws-callout">This map uses real Vicmap roads. Works notices are simulated and located at reference intersections, not verified works boundaries. It excludes worker locations and health data. Nothing is published to Google Maps or Waze.</div><div class="two-columns">${card('Road user works map','Vicmap reference intersection / simulated session-only notices',`${publicMap()}${body(`${workerSafety.sites.filter(s=>s.notice.published).map(s=>{const p=s.notice.published;return `<article class="ws-public-notice"><h3>${esc(p.location)} · ${esc(p.road)}</h3><p>${esc(dateLabel(p.start))} — ${esc(dateLabel(p.end))}</p><p>${esc(p.impact)}</p>${badge('Confirmed / own map preview')}</article>`;}).join('')||'<div class="empty">No notices published. Confirm the works details to update the preview.</div>'}`)}`)}${card('Works details & publication preview',site.name+' · Melbourne local time',body(`<div class="ws-form"><label class="ws-field">Start date and time<input type="datetime-local" aria-label="Works start date and time" data-ws-input="notice.start" value="${esc(n.start)}"></label><label class="ws-field">End date and time<input type="datetime-local" aria-label="Works end date and time" data-ws-input="notice.end" value="${esc(n.end)}"></label></div><label class="ws-field section-gap">Affected road section & advice<textarea rows="3" maxlength="240" aria-label="Affected road section & advice" data-ws-input="notice.impact">${esc(n.impact)}</textarea></label><div class="ws-preview"><span class="ws-label">Publication preview</span><h3>${esc(site.name)} · ${esc(site.road)}</h3><p>${esc(n.start?dateLabel(n.start):'Not set')} to ${esc(n.end?dateLabel(n.end):'Not set')}</p><p>${esc(n.impact)}</p></div>${check('Confirm the works times, impacts and advice','notice.confirmed',n.confirmed)}<div class="actions section-gap">${B('Update map preview','publish','','primary',!n.confirmed)}${B('Extend by 2 hours','extend','','small')}${B('Finish works','finish','','small',!n.published)}</div><div class="section-gap">${kv('Publication status',n.status==='published'?'Local preview updated':n.status==='ended'?'Works completed / notice removed':n.status==='changed'?'Changes unconfirmed; previous notice retained':'Draft / unpublished')}${kv('Google Maps / Waze','Not connected / nothing sent externally')}</div><p class="note">Changing the times or advice removes draft confirmation. Reconfirm before updating the public preview. Finishing works removes the map marker. External publication requires client authorisation and platform eligibility.</p>`))}</div>`;}
export function handleSafetyAction(action,value){try{const site=selectedSite(workerSafety);
 if(action==='layout-object'){selectLayoutObject(site,value);return;}
 if(action==='layout-station'){safetyInput(workerSafety,'layout.entry',value);selectLayoutObject(site,'station');return;}
 if(action==='layout-device'){safetyInput(workerSafety,'layout.cameraPosition',Number(value));selectLayoutObject(site,'sensor');return;}

 if(action==='demo-start'){const sc=LIVE_SCENARIOS[value];if(!sc)throw Error('Unknown scenario');safetyAction(workerSafety,'case',sc.case);syncDemo(demo,site);workerSafety.message='';return;}
 if(action==='demo-respond'){syncDemo(demo,site);if(!hazardEvent(site))throw Error('There is no detected hazard to respond to.');if(!responses(scenarioForCase(site.case)).some(r=>r.id===value))throw Error('Unknown response');demo.response=value;demo.respondedAt=site.clock;return;}
 if(action==='demo-reset'){safetyAction(workerSafety,'clear');site.playing=false;site.playbackRun=(site.playbackRun||0)+1;syncDemo(demo,site);workerSafety.message='';return;}
 safetyAction(workerSafety,action,value);
 if(action==='ack'&&workerSafety.tab==='live'){demo.ackAt=site.clock;workerSafety.message='';}
}catch(error){workerSafety.message=error.message;}}
export function handleSafetyInput(key,value){try{workerSafety.message='';if(key==='worker-scenario')safetyAction(workerSafety,'worker-case',value);else if(key==='worker-select')safetyAction(workerSafety,'worker-select',value);else if(key==='weather-scenario')safetyAction(workerSafety,'weather-case',value);else if(key==='site')safetyAction(workerSafety,'site',value);else safetyInput(workerSafety,key,value);}catch(error){workerSafety.message=error.message;}}
export function handleSafetyFile(file){if(!file)return;if(!file.type.startsWith('video/')){workerSafety.message='Select a video file.';return;}if(localVideo)URL.revokeObjectURL(localVideo);localVideo=URL.createObjectURL(file);workerSafety.message='Local video loaded for replay only. Detection and upload are not enabled.';}
export function refreshSafety(seconds){const site=selectedSite(workerSafety),wasPlaying=site.playing,before=JSON.stringify(site.events),liveTab=workerSafety.tab==='live',phaseBefore=liveTab?livePhase(site,syncDemo(demo,site)):null;tickSafety(workerSafety,seconds);
 if(liveTab){syncDemo(demo,site);holdAtDetection(site,demo);if(livePhase(site,demo)!==phaseBefore)return true;if(site.playing)for(const el of document.querySelectorAll('[data-live-object]'))el.style.transform=liveObjectTransform(site,el.dataset.liveObject);return before!==JSON.stringify(site.events);}
 return before!==JSON.stringify(site.events)||(wasPlaying&&!site.playing);}
export function exportSafety(){return safetyExport(workerSafety);}

export function paintSafety(){const root=document.querySelector('#view');if(!root)return;const supportOpen=Array.from(root.querySelectorAll('[data-support-details][open]'),el=>el.dataset.supportDetails),focused=document.activeElement,focusKey=focused?.dataset?.wsInput,focusAction=focused?.dataset?.ws,focusValue=focused?.dataset?.value;const oldVideo=root.querySelector('[data-local-video]'),connectivityOpen=root.querySelector('[data-connectivity]')?.open;root.innerHTML=safetyPage();for(const el of root.querySelectorAll('[data-support-details]'))el.open=supportOpen.includes(el.dataset.supportDetails);if(['worker','layout'].includes(workerSafety.tab)){const target=Array.from(root.querySelectorAll('[data-ws-input],[data-ws]')).find(el=>focusKey?el.dataset.wsInput===focusKey:focusAction&&el.dataset.ws===focusAction&&el.dataset.value===focusValue);(target|| (focusAction?root.querySelector('[data-ws=complete-support],[data-ws=arrange-support]'):null))?.focus({preventScroll:true});}const connectivity=root.querySelector('[data-connectivity]');if(connectivity)connectivity.open=Boolean(connectivityOpen);const newVideo=root.querySelector('[data-local-video]');if(localVideo&&oldVideo?.querySelector('video')&&newVideo){const player=oldVideo.querySelector('video');if(player.src!==localVideo)player.src=localVideo;newVideo.replaceWith(oldVideo);}else if(localVideo&&newVideo)newVideo.open=true;}
